import { styled, Text, View } from '@tamagui/web';
import type { ReactElement } from 'react';

import { cx } from '../../helpers/composeClassNames';
import type { ElementProps } from '../../types/ElementProps';
import { Box } from '../Box';
import { Button } from '../Button';
import { Skeleton } from '../Skeleton';

export type CodeSnippetProps = ElementProps<HTMLPreElement> & {
	children: string;
	buttonText?: string;
	buttonDisabled?: boolean;
	onClick?: () => void;
};

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

// Declared where they render: zero-runtime only erases a `styled()` whose every use is in its own module
const CodeSnippetFrame = styled(View, {
	render: 'pre',
	display: 'flex',
	flexDirection: 'row',
	alignItems: 'center',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: '3.75rem',
	justifyContent: 'space-between',
	width: '100%',
	padding: '16px',
	color: 'var(--rcx-color-font-default, #2f343d)',
	borderRadius: 'var(--rcx-code-snippet-border-radius, var(--rcx-border-radius-medium, 0.25rem))',
	backgroundColor: 'var(--rcx-color-surface-neutral, #e4e7ea)',
});

const CodeSnippetCodeBoxFrame = styled(Text, {
	flexBasis: 'auto',
	wordWrap: 'inherit',
	render: 'div',
	display: 'block',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	marginRight: '8px',
	whiteSpace: 'pre-line',
	wordBreak: 'break-all',
	fontFamily: 'monospace',
});

// end of generated

/**
 * The `CodeSnippet` is used to show code or commands and make easier to copy them.
 *
 * The default button text is `Copy` but you can use the `buttonText` prop to handle translations in your project.
 *
 * Please check the `useClipBoard` hook in `fuselage-hooks` package, to handle the copy behaviour.
 */
const CodeSnippet = ({
	children,
	onClick,
	buttonText = 'Copy',
	buttonDisabled = false,
	className,
	...props
}: CodeSnippetProps): ReactElement<CodeSnippetProps> => {
	if (!children) {
		return (
			<CodeSnippetFrame render={<pre {...props} />} className={cx('rcx-box rcx-box--full', 'rcx-code-snippet', className)}>
				<Skeleton width='100%' aria-hidden aria-busy />
			</CodeSnippetFrame>
		);
	}

	return (
		<CodeSnippetFrame render={<pre {...props} />} className={cx('rcx-box rcx-box--full', 'rcx-code-snippet', className)}>
			<CodeSnippetCodeBoxFrame render={<div role='code' />} className='rcx-box rcx-box--full rcx-code-snippet__codebox'>
				{children}
			</CodeSnippetCodeBoxFrame>
			{onClick && children && (
				<Box>
					<Button size='small' variant='primary' onClick={onClick} disabled={buttonDisabled}>
						{buttonText}
					</Button>
				</Box>
			)}
		</CodeSnippetFrame>
	);
};

export default CodeSnippet;
